FILES = {'src/az_enterprise/core/director_policy_alpha293.py': '"""ATLAS ZERO Alpha 2.9.3 — Director Policy & Project Strategy."""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom enum import Enum\nfrom typing import Any, Mapping, Sequence\n\n\nclass ProjectType(str, Enum):\n    DOCUMENTARY = "DOCUMENTARY"\n    YOUTUBE = "YOUTUBE"\n    SHORT_FORM = "SHORT_FORM"\n    ADVERTISEMENT = "ADVERTISEMENT"\n    EDUCATIONAL = "EDUCATIONAL"\n    SHORT_FILM = "SHORT_FILM"\n    CUSTOM = "CUSTOM"\n\n\nclass ProjectObjective(str, Enum):\n    RETENTION = "RETENTION"\n    EMOTION = "EMOTION"\n    ACCURACY = "ACCURACY"\n    CONVERSION = "CONVERSION"\n    CLARITY = "CLARITY"\n    PRESTIGE = "PRESTIGE"\n    BALANCED = "BALANCED"\n\n\n@dataclass(frozen=True)\nclass QualityProfile:\n    """Weighted evaluation profile used by Director AI."""\n\n    weights: Mapping[str, float]\n    release_threshold: float = 0.80\n    rework_threshold: float = 0.55\n\n    def __post_init__(self) -> None:\n        if not self.weights:\n            raise ValueError("quality profile requires at least one criterion")\n\n        for criterion, weight in self.weights.items():\n            if not criterion.strip():\n                raise ValueError("quality criterion cannot be empty")\n            if weight < 0:\n                raise ValueError("quality weights cannot be negative")\n\n        total = sum(self.weights.values())\n        if total <= 0:\n            raise ValueError("quality weights total must be greater than zero")\n\n        if not 0.0 <= self.rework_threshold <= 1.0:\n            raise ValueError("rework_threshold must be between 0.0 and 1.0")\n        if not 0.0 <= self.release_threshold <= 1.0:\n            raise ValueError("release_threshold must be between 0.0 and 1.0")\n        if self.rework_threshold > self.release_threshold:\n            raise ValueError("rework_threshold cannot exceed release_threshold")\n\n    def normalized_weights(self) -> dict[str, float]:\n        total = sum(self.weights.values())\n        return {key: value / total for key, value in self.weights.items()}\n\n    def score(self, metrics: Mapping[str, float]) -> float:\n        normalized = self.normalized_weights()\n        missing = [criterion for criterion in normalized if criterion not in metrics]\n        if missing:\n            raise ValueError(\n                "missing quality metrics: " + ", ".join(sorted(missing))\n            )\n\n        score = 0.0\n        for criterion, weight in normalized.items():\n            value = metrics[criterion]\n            if not 0.0 <= value <= 1.0:\n                raise ValueError(\n                    f"metric \'{criterion}\' must be between 0.0 and 1.0"\n                )\n            score += value * weight\n        return score\n\n\n@dataclass(frozen=True)\nclass MandatoryConstraint:\n    name: str\n    expected: Any\n    description: str = ""\n\n    def __post_init__(self) -> None:\n        if not self.name.strip():\n            raise ValueError("constraint name cannot be empty")\n\n\n@dataclass(frozen=True)\nclass DirectorPolicy:\n    """Project-level decision policy owned by Director AI."""\n\n    project_type: ProjectType\n    objective: ProjectObjective\n    quality_profile: QualityProfile\n    constraints: tuple[MandatoryConstraint, ...] = ()\n    allowed_rework_targets: tuple[str, ...] = ()\n    metadata: Mapping[str, Any] = field(default_factory=dict)\n\n    def validate_constraints(\n        self,\n        project_facts: Mapping[str, Any],\n    ) -> tuple[str, ...]:\n        violations: list[str] = []\n        for constraint in self.constraints:\n            actual = project_facts.get(constraint.name)\n            if actual != constraint.expected:\n                violations.append(\n                    f"{constraint.name}: expected {constraint.expected!r}, "\n                    f"got {actual!r}"\n                )\n        return tuple(violations)\n\n    def validate_rework_targets(\n        self,\n        targets: Sequence[str],\n    ) -> tuple[str, ...]:\n        if not self.allowed_rework_targets:\n            return tuple(targets)\n\n        allowed = set(self.allowed_rework_targets)\n        invalid = [target for target in targets if target not in allowed]\n        if invalid:\n            raise ValueError(\n                "rework targets are not allowed by policy: "\n                + ", ".join(sorted(set(invalid)))\n            )\n        return tuple(targets)\n\n\n@dataclass(frozen=True)\nclass ProjectEvaluation:\n    score: float\n    constraint_violations: tuple[str, ...]\n    metrics: Mapping[str, float]\n\n    @property\n    def constraints_passed(self) -> bool:\n        return not self.constraint_violations\n\n\nclass DirectorPolicyEvaluator:\n    """Deterministic policy evaluation before AI interpretation."""\n\n    def evaluate(\n        self,\n        policy: DirectorPolicy,\n        metrics: Mapping[str, float],\n        project_facts: Mapping[str, Any],\n    ) -> ProjectEvaluation:\n        return ProjectEvaluation(\n            score=policy.quality_profile.score(metrics),\n            constraint_violations=policy.validate_constraints(project_facts),\n            metrics=dict(metrics),\n        )\n', 'src/az_enterprise/core/director_policy_evaluator_alpha293.py': '"""Policy-aware decision evaluator for Director Supervisor Alpha 2.9.3."""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Any, Mapping\n\nfrom az_enterprise.core.director_policy_alpha293 import (\n    DirectorPolicy,\n    DirectorPolicyEvaluator,\n)\nfrom az_enterprise.core.director_supervisor_alpha292 import (\n    DecisionStatus,\n    DirectorAction,\n    DirectorDecision,\n)\n\n\n@dataclass(frozen=True)\nclass RuntimeReport:\n    metrics: Mapping[str, float]\n    project_facts: Mapping[str, Any]\n    recommended_targets: tuple[str, ...] = ()\n    metadata: Mapping[str, Any] | None = None\n\n\nclass PolicyDecisionEvaluator:\n    """Converts runtime reports into Director decisions.\n\n    This evaluator is intentionally deterministic. A later AI evaluator may\n    enrich the reasoning, but it must still obey the DirectorPolicy.\n    """\n\n    def __init__(self, policy: DirectorPolicy) -> None:\n        self._policy = policy\n        self._evaluator = DirectorPolicyEvaluator()\n\n    def __call__(self, runtime_result: Any, cycle: int) -> DirectorDecision:\n        report = self._coerce_report(runtime_result)\n        evaluation = self._evaluator.evaluate(\n            self._policy,\n            report.metrics,\n            report.project_facts,\n        )\n\n        if evaluation.constraint_violations:\n            return DirectorDecision(\n                status=DecisionStatus.REJECT,\n                reason=(\n                    "Mandatory constraints failed: "\n                    + "; ".join(evaluation.constraint_violations)\n                ),\n                confidence=1.0,\n                metadata={\n                    "score": evaluation.score,\n                    "cycle": cycle,\n                    "violations": evaluation.constraint_violations,\n                },\n            )\n\n        profile = self._policy.quality_profile\n\n        if evaluation.score >= profile.release_threshold:\n            return DirectorDecision(\n                status=DecisionStatus.APPROVE,\n                reason=(\n                    f"Project score {evaluation.score:.3f} reached "\n                    f"release threshold {profile.release_threshold:.3f}"\n                ),\n                confidence=evaluation.score,\n                metadata={"score": evaluation.score, "cycle": cycle},\n            )\n\n        if evaluation.score >= profile.rework_threshold:\n            targets = self._policy.validate_rework_targets(\n                report.recommended_targets\n            )\n            if not targets:\n                return DirectorDecision(\n                    status=DecisionStatus.ESCALATE,\n                    reason=(\n                        "Project requires rework, but no valid rework targets "\n                        "were provided"\n                    ),\n                    confidence=1.0 - evaluation.score,\n                    metadata={"score": evaluation.score, "cycle": cycle},\n                )\n\n            return DirectorDecision(\n                status=DecisionStatus.REWORK,\n                reason=(\n                    f"Project score {evaluation.score:.3f} is below "\n                    f"release threshold {profile.release_threshold:.3f}"\n                ),\n                confidence=max(evaluation.score, 0.5),\n                actions=tuple(\n                    DirectorAction(\n                        target=target,\n                        reason="Requested by policy evaluation",\n                    )\n                    for target in targets\n                ),\n                metadata={"score": evaluation.score, "cycle": cycle},\n            )\n\n        return DirectorDecision(\n            status=DecisionStatus.REJECT,\n            reason=(\n                f"Project score {evaluation.score:.3f} is below "\n                f"minimum rework threshold {profile.rework_threshold:.3f}"\n            ),\n            confidence=1.0 - evaluation.score,\n            metadata={"score": evaluation.score, "cycle": cycle},\n        )\n\n    @staticmethod\n    def _coerce_report(runtime_result: Any) -> RuntimeReport:\n        if isinstance(runtime_result, RuntimeReport):\n            return runtime_result\n\n        if isinstance(runtime_result, Mapping):\n            return RuntimeReport(\n                metrics=runtime_result.get("metrics", {}),\n                project_facts=runtime_result.get("project_facts", {}),\n                recommended_targets=tuple(\n                    runtime_result.get("recommended_targets", ())\n                ),\n                metadata=runtime_result.get("metadata"),\n            )\n\n        raise TypeError(\n            "runtime result must be RuntimeReport or mapping"\n        )\n', 'tests/test_director_policy_alpha293.py': 'from __future__ import annotations\n\nimport pytest\n\nfrom az_enterprise.core.director_policy_alpha293 import (\n    DirectorPolicy,\n    DirectorPolicyEvaluator,\n    MandatoryConstraint,\n    ProjectObjective,\n    ProjectType,\n    QualityProfile,\n)\nfrom az_enterprise.core.director_policy_evaluator_alpha293 import (\n    PolicyDecisionEvaluator,\n    RuntimeReport,\n)\nfrom az_enterprise.core.director_supervisor_alpha292 import DecisionStatus\n\n\ndef make_policy():\n    return DirectorPolicy(\n        project_type=ProjectType.DOCUMENTARY,\n        objective=ProjectObjective.ACCURACY,\n        quality_profile=QualityProfile(\n            weights={\n                "accuracy": 0.5,\n                "retention": 0.3,\n                "technical": 0.2,\n            },\n            release_threshold=0.80,\n            rework_threshold=0.55,\n        ),\n        constraints=(\n            MandatoryConstraint("language", "en"),\n            MandatoryConstraint("duration_ok", True),\n        ),\n        allowed_rework_targets=("research", "visual", "timeline"),\n    )\n\n\ndef test_quality_profile_normalizes_and_scores():\n    profile = QualityProfile(\n        weights={"a": 2.0, "b": 1.0},\n        release_threshold=0.8,\n        rework_threshold=0.5,\n    )\n\n    assert profile.normalized_weights() == pytest.approx(\n        {"a": 2 / 3, "b": 1 / 3}\n    )\n    assert profile.score({"a": 0.9, "b": 0.6}) == pytest.approx(0.8)\n\n\ndef test_missing_metric_is_rejected():\n    profile = QualityProfile(weights={"accuracy": 1.0})\n\n    with pytest.raises(ValueError, match="missing quality metrics"):\n        profile.score({})\n\n\ndef test_constraint_validation_reports_violation():\n    policy = make_policy()\n\n    violations = policy.validate_constraints(\n        {"language": "es", "duration_ok": True}\n    )\n\n    assert len(violations) == 1\n    assert "language" in violations[0]\n\n\ndef test_policy_evaluator_approves_release():\n    evaluator = PolicyDecisionEvaluator(make_policy())\n\n    decision = evaluator(\n        RuntimeReport(\n            metrics={\n                "accuracy": 0.95,\n                "retention": 0.80,\n                "technical": 0.85,\n            },\n            project_facts={"language": "en", "duration_ok": True},\n        ),\n        cycle=0,\n    )\n\n    assert decision.status is DecisionStatus.APPROVE\n\n\ndef test_policy_evaluator_requests_targeted_rework():\n    evaluator = PolicyDecisionEvaluator(make_policy())\n\n    decision = evaluator(\n        RuntimeReport(\n            metrics={\n                "accuracy": 0.70,\n                "retention": 0.65,\n                "technical": 0.75,\n            },\n            project_facts={"language": "en", "duration_ok": True},\n            recommended_targets=("research", "timeline"),\n        ),\n        cycle=0,\n    )\n\n    assert decision.status is DecisionStatus.REWORK\n    assert tuple(action.target for action in decision.actions) == (\n        "research",\n        "timeline",\n    )\n\n\ndef test_policy_evaluator_rejects_constraint_failure():\n    evaluator = PolicyDecisionEvaluator(make_policy())\n\n    decision = evaluator(\n        RuntimeReport(\n            metrics={\n                "accuracy": 0.95,\n                "retention": 0.95,\n                "technical": 0.95,\n            },\n            project_facts={"language": "es", "duration_ok": True},\n        ),\n        cycle=0,\n    )\n\n    assert decision.status is DecisionStatus.REJECT\n    assert "Mandatory constraints failed" in decision.reason\n\n\ndef test_low_score_is_rejected():\n    evaluator = PolicyDecisionEvaluator(make_policy())\n\n    decision = evaluator(\n        RuntimeReport(\n            metrics={\n                "accuracy": 0.30,\n                "retention": 0.30,\n                "technical": 0.30,\n            },\n            project_facts={"language": "en", "duration_ok": True},\n        ),\n        cycle=0,\n    )\n\n    assert decision.status is DecisionStatus.REJECT\n\n\ndef test_rework_without_targets_escalates():\n    evaluator = PolicyDecisionEvaluator(make_policy())\n\n    decision = evaluator(\n        RuntimeReport(\n            metrics={\n                "accuracy": 0.70,\n                "retention": 0.65,\n                "technical": 0.75,\n            },\n            project_facts={"language": "en", "duration_ok": True},\n        ),\n        cycle=0,\n    )\n\n    assert decision.status is DecisionStatus.ESCALATE\n\n\ndef test_disallowed_rework_target_is_rejected():\n    evaluator = PolicyDecisionEvaluator(make_policy())\n\n    with pytest.raises(ValueError, match="not allowed"):\n        evaluator(\n            RuntimeReport(\n                metrics={\n                    "accuracy": 0.70,\n                    "retention": 0.65,\n                    "technical": 0.75,\n                },\n                project_facts={"language": "en", "duration_ok": True},\n                recommended_targets=("packaging",),\n            ),\n            cycle=0,\n        )\n\n\ndef test_policy_evaluation_object():\n    evaluation = DirectorPolicyEvaluator().evaluate(\n        make_policy(),\n        metrics={\n            "accuracy": 0.8,\n            "retention": 0.8,\n            "technical": 0.8,\n        },\n        project_facts={"language": "en", "duration_ok": True},\n    )\n\n    assert evaluation.score == pytest.approx(0.8)\n    assert evaluation.constraints_passed is True\n', 'docs/architecture/alpha_293_director_policy.md': '# ATLAS ZERO Alpha 2.9.3 — Director Policy & Project Strategy\n\n## Purpose\n\nAlpha 2.9.3 gives Director AI an explicit project strategy instead of\nhard-coded universal quality rules.\n\nThe policy defines:\n\n- project type;\n- primary objective;\n- weighted quality criteria;\n- release and rework thresholds;\n- mandatory constraints;\n- modules that may be targeted for rework.\n\n## Architectural rule\n\nWorker modules may:\n\n- analyze;\n- generate reports;\n- recommend actions;\n- produce candidate artifacts.\n\nWorker modules may not:\n\n- approve a project;\n- reject a project;\n- change project strategy;\n- authorize release;\n- directly trigger uncontrolled project mutation.\n\nAll project-level decisions belong to Director AI.\n\n## Decision order\n\n1. Validate mandatory constraints.\n2. Calculate weighted quality score.\n3. Compare the score with policy thresholds.\n4. Validate proposed rework targets.\n5. Emit one decision:\n   - `APPROVE`\n   - `REWORK`\n   - `REJECT`\n   - `ESCALATE`\n\n## Deliberate limitations\n\nThis version does not add:\n\n- Director Council;\n- multiple internal agents;\n- autonomous learning;\n- persistent memory;\n- dynamic policy generation.\n\nThe policy is explicit, deterministic, and testable.\n'}

def main():
    root = Path.cwd()
    for relative_path, content in FILES.items():
        target = root / relative_path
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            backup = target.with_suffix(target.suffix + ".bak")
            backup.write_text(target.read_text(encoding="utf-8"), encoding="utf-8")
            print(f"BACKUP  {backup}")
        target.write_text(content, encoding="utf-8")
        print(f"CREATED {target}")

    print("\nRun:")
    print("python -m pytest tests/test_director_policy_alpha293.py -v")

if __name__ == "__main__":
    main()
